LEVEL = 1
CFG = {1: 2, 2: 3, 3: 5}
N = CFG[LEVEL]
shards = ["shard-%d@region-%d" % (i, i % N) for i in range(N * 2)]
per_region = {}
for s in shards:
    r = s.split("@")[1]; per_region[r] = per_region.get(r, 0) + 1
print("shards:", len(shards), "| per region:", per_region, "| any region complete:", any(v == len(shards) for v in per_region.values()))

